gcX(){return"\u10d0\u10db \u10eb\u10d8\u10d4\u10d1\u10d0\u10e8\u10d8 \u10d8\u10dc\u10e4\u10dd\u10e0\u10db\u10d0\u10ea\u10d8\u10d0 \u10d0\u10e0 \u10db\u10dd\u10d8\u10eb\u10d4\u10d1\u10dc\u10d0"},
gdN(){return"\u10d3\u10d0\u10da\u10d0\u10d2\u10d4\u10d1\u10d0 \u10e1\u10d0\u10d7\u10d0\u10e3\u10e0\u10d8\u10d7"},
gdM(){return"\u10d3\u10d0\u10da\u10d0\u10d2\u10d4\u10d1\u10d0 \u10d0\u10e6\u10ec\u10d4\u10e0\u10d8\u10da\u10dd\u10d1\u10d8\u10d7"},
geL(){return"\u10d3\u10d0\u10da\u10d0\u10d2\u10d4\u10d1\u10d0 \u10e1\u10d0\u10ee\u10d4\u10da\u10d8\u10d7"},
geM(){return"\u10d3\u10d0\u10da\u10d0\u10d2\u10d4\u10d1\u10d0 \u10de\u10dd\u10d6\u10d8\u10ea\u10d8\u10d8\u10d7"},
gdL(){return"\u10d0\u10db \u10d2\u10d0\u10dc\u10e7\u10dd\u10e4\u10d8\u10da\u10d4\u10d1\u10d0\u10e8\u10d8 \u10d0\u10e0\u10d0\u10e4\u10d4\u10e0\u10d8 \u10db\u10dd\u10d8\u10eb\u10d4\u10d1\u10dc\u10d0"},
gcN(a){return"\u10eb\u10d8\u10d4\u10d1\u10d0"},
gei(){return"ka"},
ger(){return"\u10d2\u10d0\u10d4\u10e0\u10d7\u10d8\u10d0\u10dc\u10d4\u10d1\u10d0"},
gdu(){return"\u10db\u10d8\u10db\u10d3\u10d8\u10dc\u10d0\u10e0\u10d4\u10dd\u10d1\u10e1 \u10d3\u10d0\u10d9\u10d0\u10d5\u10e8\u10d8\u10e0\u10d4\u10d1\u10d0"},
gcM(){return"\u10db\u10d4\u10e2\u10d8"},
gcL(){return"\u10dc\u10d0\u10d9\u10da\u10d4\u10d1\u10d8"},
geh(){return"\u10db\u10dd\u10dc\u10d0\u10ec\u10d8\u10da\u10d4\u10d4\u10d1\u10d8"},
gem(){return"\u10dc\u10d0\u10ee\u10d5\u10d0"},
gca(a){return"\u10d3\u10d0\u10ee\u10e3\u10e0\u10d5\u10d0"},
geR(a){return"\u10d5\u10d4\u10e0\u10e1\u10d8\u10d0"},
gev(a){return"\u10e9\u10d0\u10db\u10dd\u10e2\u10d5\u10d8\u10e0\u10d7\u10d5\u10d0"},
gex(){return"\u10d4\u10e1 \u10d4\u10da.\u10e4\u10dd\u10e1\u10e2\u10d0 \u10d0\u10e0 \u10d0\u10e0\u10d8\u10e1 \u10d5\u10d0\u10da\u10d8\u10d3\u10e3\u10e0\u10d8"},
gep(){return"\u10d3\u10d0\u10d0\u10db\u10d0\u10e2\u10d4\u10d7 \u10d7\u10e5\u10d5\u10d4\u10dc\u10d8 \u10d4\u10da.\u10e4\u10dd\u10e1\u10e2\u10d0"},
geS(){return"\u10e0\u10d0 \u10d0\u10e0\u10d8\u10e1 Edhomy?"},
gew(){return"Edhomy \u10d0\u10e0\u10d8\u10e1 \u10e1\u10d0\u10d2\u10d0\u10dc\u10db\u10d0\u10dc\u10d0\u10d7\u10da\u10d4\u10d1\u10da\u10dd \u10de\u10da\u10d0\u10e2\u10e4\u10dd\u10e0\u10db\u10d0, \u10e1\u10d0\u10d3\u10d0\u10ea \u10e8\u10d4\u10d2\u10d8\u10eb\u10da\u10d8\u10d0\u10d7 \u10db\u10d0\u10e0\u10d7\u10d4\u10d1\u10e3\u10da\u10d8 \u10e8\u10d4\u10db\u10dd\u10e1\u10d0\u10d5\u10d0\u10da\u10d8 \u10db\u10d8\u10d8\u10e6\u10dd\u10d7 \u10e0\u10dd\u10d2\u10dd\u10e0\u10ea \u10d0\u10e6\u10db\u10d6\u10e0\u10d3\u10d4\u10da\u10db\u10d0 \u10d0\u10dc \u10d9\u10dd\u10dc\u10e2\u10d4\u10dc\u10e2\u10d8\u10e1 \u10e8\u10d4\u10db\u10e5\u10db\u10dc\u10d4\u10da\u10db\u10d0 \u10d2\u10d0\u10db\u10dd\u10ec\u10d4\u10e0\u10d4\u10d1\u10d8\u10e1 \u10d3\u10d0 \u10e1\u10d0\u10e9\u10e3\u10e5\u10e0\u10d4\u10d1\u10d8\u10e1 \u10db\u10d4\u10e8\u10d5\u10d4\u10dd\u10d1\u10d8\u10d7. \u10d0\u10d1\u10dd\u10dc\u10d4\u10dc\u10e2\u10d4\u10d1\u10d8 \u10e1\u10d0\u10e0\u10d2\u10d4\u10d1\u10da\u10dd\u10d1\u10d4\u10dc \u10ee\u10d4\u10da\u10db\u10d8\u10e1\u10d0\u10ec\u10d5\u10d3\u10dd\u10db \u10e4\u10d0\u10e1\u10d4\u10d1\u10d8\u10d7 \u10d3\u10d0 \u10e1\u10ec\u10d0\u10d5\u10da\u10dd\u10d1\u10d4\u10dc AI-\u10d8\u10e1 \u10db\u10ee\u10d0\u10e0\u10d3\u10d0\u10ed\u10d4\u10e0\u10d8\u10da\u10d8 \u10d9\u10e3\u10e0\u10e1\u10d4\u10d1\u10d8\u10d7, \u10d5\u10d8\u10d3\u10d4\u10dd\u10d9\u10dd\u10dc\u10e4\u10d4\u10e0\u10d4\u10dc\u10ea\u10d8\u10d4\u10d1\u10d8\u10d7 \u10d3\u10d0 \u10db\u10dd\u10d9\u10da\u10d4 \u10d5\u10d8\u10d3\u10d4\u10dd\u10d4\u10d1\u10d8\u10d7, \u10e0\u10dd\u10db\u10da\u10d4\u10d1\u10e1\u10d0\u10ea Globals \u10e3\u10ec\u10dd\u10d3\u10d4\u10d1\u10d4\u10dc."},
geq(){return"\u10e8\u10d4\u10d5\u10d8\u10eb\u10da\u10d8\u10d0 \u10d0\u10de\u10da\u10d8\u10d9\u10d0\u10ea\u10d8\u10d8\u10d7 \u10e4\u10e3\u10da\u10d8\u10e1 \u10e8\u10dd\u10d5\u10dc\u10d0?"},
geO(){return"\u10d3\u10d8\u10d0\u10ee, \u10e8\u10d4\u10d2\u10d8\u10eb\u10da\u10d8\u10d0\u10d7 \u10e8\u10d4\u10e5\u10db\u10dc\u10d0\u10d7 \u10e8\u10d4\u10db\u10e5\u10db\u10dc\u10d4\u10da\u10d8\u10e1 \u10d0\u10dc\u10d2\u10d0\u10e0\u10d8\u10e8\u10d8 \u10d0\u10e6\u10db\u10d6\u10e0\u10d3\u10d4\u10da\u10d8\u10e1 \u10d0\u10dc \u10de\u10e0\u10dd\u10e4\u10d4\u10e1\u10d8\u10dd\u10dc\u10d0\u10da\u10d8\u10e1 \u10e1\u10d0\u10ee\u10d8\u10d7. \u10e8\u10d4\u10db\u10d3\u10d4\u10d2 \u10e9\u10d5\u10d4\u10dc \u10d5\u10d0\u10db\u10dd\u10ec\u10db\u10d4\u10d1\u10d7 \u10d7\u10e5\u10d5\u10d4\u10dc\u10e1 \u10d3\u10d8\u10de\u10da\u10dd\u10db\u10e1 \u10d0\u10dc \u10e1\u10d4\u10e0\u10e2\u10d8\u10e4\u10d8\u10d9\u10d0\u10e2\u10e1 \u10d3\u10d0 \u10e8\u10d4\u10d2\u10d8\u10eb\u10da\u10d8\u10d0\u10d7 \u10d3\u10d0\u10d8\u10ec\u10e7\u10dd\u10d7 \u10d7\u10e5\u10d5\u10d4\u10dc\u10d8 \u10d9\u10dd\u10dc\u10e2\u10d4\u10dc\u10e2\u10d8\u10e1 \u10d2\u10d0\u10d6\u10d8\u10d0\u10e0\u10d4\u10d1\u10d0 \u10d3\u10d0 \u10d0\u10ee\u10d0\u10da\u10d8 \u10d0\u10d1\u10dd\u10dc\u10d4\u10dc\u10e2\u10d4\u10d1\u10d8\u10e1 \u10db\u10dd\u10d6\u10d8\u10d3\u10d5\u10d0. \u10d7\u10e3 \u10d0\u10e0 \u10d2\u10d0\u10e5\u10d5\u10d7 \u10d3\u10d8\u10de\u10da\u10dd\u10db\u10d8 \u10d0\u10dc \u10e1\u10d4\u10e0\u10e2\u10d8\u10e4\u10d8\u10d9\u10d0\u10e2\u10d8, \u10db\u10ee\u10dd\u10da\u10dd\u10d3 \u10e1\u10d0\u10e9\u10e3\u10e5\u10e0\u10d4\u10d1\u10d8\u10d7 \u10e8\u10d4\u10d2\u10d8\u10eb\u10da\u10d8\u10d0\u10d7 \u10d2\u10d0\u10db\u10dd\u10d8\u10db\u10e3\u10e8\u10d0\u10dd\u10d7."},
geI(){return"\u10d4\u10e1 \u10de\u10da\u10d0\u10e2\u10e4\u10dd\u10e0\u10db\u10d0 \u10e3\u10e1\u10d0\u10e4\u10e0\u10d7\u10ee\u10dd\u10d0?"},
geH(){return"\u10d3\u10d8\u10d0\u10ee, \u10e9\u10d5\u10d4\u10dc \u10d0\u10e0 \u10d5\u10e7\u10d8\u10d3\u10d8\u10d7 \u10d7\u10e5\u10d5\u10d4\u10dc\u10e1 \u10db\u10dd\u10dc\u10d0\u10ea\u10d4\u10db\u10d4\u10d1\u10e1 \u10db\u10d4\u10e1\u10d0\u10db\u10d4 \u10db\u10ee\u10d0\u10e0\u10d4\u10d4\u10d1\u10e1. \u10e8\u10d4\u10d2\u10d8\u10eb\u10da\u10d8\u10d0\u10d7 \u10d2\u10e5\u10dd\u10dc\u10d3\u10d4\u10d7 \u10de\u10d8\u10e0\u10d0\u10d3\u10d8 \u10d0\u10dc\u10d2\u10d0\u10e0\u10d8\u10e8\u10d8. \u10dc\u10d4\u10d1\u10d8\u10e1\u10db\u10d8\u10d4\u10e0\u10d8 \u10e9\u10d0\u10e2\u10d8 \u10d8\u10ec\u10e7\u10d4\u10d1\u10d0 \u10d7\u10e5\u10d5\u10d4\u10dc\u10d8 \u10d3\u10d0\u10e1\u10e2\u10e3\u10e0\u10d8\u10e1 \u10e8\u10d4\u10db\u10d3\u10d4\u10d2 \u10de\u10d8\u10e0\u10d5\u10d4\u10da \u10e8\u10d4\u10e2\u10e7\u10dd\u10d1\u10d8\u10dc\u10d4\u10d1\u10d0\u10d6\u10d4. \u10e1\u10d0\u10e3\u10d1\u10e0\u10d4\u10d1\u10d8, \u10de\u10d0\u10e0\u10dd\u10da\u10d4\u10d1\u10d8 \u10d3\u10d0 \u10e1\u10d0\u10d1\u10d0\u10dc\u10d9\u10dd \u10d8\u10dc\u10e4\u10dd\u10e0\u10db\u10d0\u10ea\u10d8\u10d0 \u10db\u10d7\u10da\u10d8\u10d0\u10dc\u10d0\u10d3 \u10d3\u10d0\u10e8\u10d8\u10e4\u10e0\u10e3\u10da\u10d8\u10d0. \u10e9\u10d5\u10d4\u10dc \u10d5\u10ee\u10d4\u10d3\u10d0\u10d5\u10d7 \u10d7\u10e5\u10d5\u10d4\u10dc\u10e1 \u10d8\u10dc\u10e4\u10dd\u10e0\u10db\u10d0\u10ea\u10d8\u10d0\u10e1 \u10db\u10ee\u10dd\u10da\u10dd\u10d3 \u10d7\u10e3 \u10d0\u10e0\u10d8\u10e1 \u10e8\u10d4\u10e2\u10e7\u10dd\u10d1\u10d8\u10dc\u10d4\u10d1\u10d0 \u10d0\u10dc \u10d7\u10e5\u10d5\u10d4\u10dc \u10d8\u10d7\u10ee\u10dd\u10d5\u10d7 \u10d7\u10d0\u10dc\u10ee\u10d8\u10e1 \u10d2\u10d0\u10db\u10dd\u10e2\u10d0\u10dc\u10d0\u10e1."},
